import{_ as t,a as r,b as a}from"./chunks/dashboard-settings-billing.CLIYBQtr.js";import{_ as i,o,c as n,a2 as s}from"./chunks/framework.CCXDMzJr.js";const S=JSON.parse('{"title":"Enterprise Architecture & SaaS Dashboard Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),l={name:"guide/architecture.md"};function c(d,e,p,u,h,g){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="enterprise-architecture-saas-dashboard-overview" tabindex="-1">Enterprise Architecture &amp; SaaS Dashboard Overview <a class="header-anchor" href="#enterprise-architecture-saas-dashboard-overview" aria-label="Permalink to &quot;Enterprise Architecture &amp; SaaS Dashboard Overview&quot;">​</a></h1><p>Slicemeter uses a dual-engine architecture designed to support both <strong>Cloud SaaS</strong> and <strong>100% Enterprise Air-Gapped</strong> deployments.</p><hr><h2 id="enterprise-dashboard-visual-interface" tabindex="-1">Enterprise Dashboard Visual Interface <a class="header-anchor" href="#enterprise-dashboard-visual-interface" aria-label="Permalink to &quot;Enterprise Dashboard Visual Interface&quot;">​</a></h2><h3 id="_1-cost-explorer-multi-cluster-chargeback-ledger" tabindex="-1">1. Cost Explorer &amp; Multi-Cluster Chargeback Ledger <a class="header-anchor" href="#_1-cost-explorer-multi-cluster-chargeback-ledger" aria-label="Permalink to &quot;1. Cost Explorer &amp; Multi-Cluster Chargeback Ledger&quot;">​</a></h3><p>The Cost Explorer provides real-time visibility into GPU spend, token intercept costs, allocated GPU-hours, and estimated waste across multi-cloud Kubernetes clusters (AKS, EKS, GKE, and local Kind).</p><p><img src="'+t+'" alt="Cost Explorer"></p><h4 id="key-capabilities" tabindex="-1">Key Capabilities: <a class="header-anchor" href="#key-capabilities" aria-label="Permalink to &quot;Key Capabilities:&quot;">​</a></h4><ul><li><strong>Memory-Weighted Proportional Attribution</strong>: Maps <code>nvidia.com/gpu</code> allocation and DCGM VRAM usage directly to namespaces.</li><li><strong>LLM Token Chargeback</strong>: Tracks prompt and completion tokens for OpenAI, Ollama, and vLLM inference workloads.</li><li><strong>1-Click Audit Exports</strong>: Generates executive PDF and CSV chargeback invoices for finance teams.</li></ul><hr><h3 id="_2-cost-optimization-waste-detection-engine" tabindex="-1">2. Cost Optimization &amp; Waste Detection Engine <a class="header-anchor" href="#_2-cost-optimization-waste-detection-engine" aria-label="Permalink to &quot;2. Cost Optimization &amp; Waste Detection Engine&quot;">​</a></h3><p>Slicemeter continuously monitors CUDA kernel calls, VRAM allocations, and CPU utilization to detect idle GPU allocations and unoptimized cloud tiers.</p><p><img src="'+r+'" alt="Waste &amp; Anomalies Engine"></p><h4 id="automated-recommendations" tabindex="-1">Automated Recommendations: <a class="header-anchor" href="#automated-recommendations" aria-label="Permalink to &quot;Automated Recommendations:&quot;">​</a></h4><ul><li><strong>Zero-GPU-Utilization Pods</strong>: Identifies pods requesting GPUs but recording 0% CUDA load for consecutive hours.</li><li><strong>On-Demand to Spot Migration</strong>: Recommends Spot instance migration for workloads running on on-demand nodes with low average utilization.</li><li><strong>Token Spike Caching</strong>: Detects redundant LLM prompt requests and suggests sidecar cache deduplication.</li></ul><hr><h3 id="_3-settings-stripe-enterprise-subscription-billing" tabindex="-1">3. Settings &amp; Stripe Enterprise Subscription Billing <a class="header-anchor" href="#_3-settings-stripe-enterprise-subscription-billing" aria-label="Permalink to &quot;3. Settings &amp; Stripe Enterprise Subscription Billing&quot;">​</a></h3><p>Manage cluster agent ingestion keys, view active license tiers, and upgrade enterprise SaaS subscriptions.</p><p><img src="'+a+'" alt="Settings &amp; Billing"></p><hr><h3 id="_4-zero-overhead-spend-forecasting-engine" tabindex="-1">4. Zero-Overhead Spend Forecasting Engine <a class="header-anchor" href="#_4-zero-overhead-spend-forecasting-engine" aria-label="Permalink to &quot;4. Zero-Overhead Spend Forecasting Engine&quot;">​</a></h3><p>Slicemeter includes a native, CPU-friendly time-series forecasting engine that predicts month-end GPU spend and token consumption without requiring external ML Python runtimes or heavy compute infrastructure.</p><h4 id="highlights" tabindex="-1">Highlights: <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights:&quot;">​</a></h4><ul><li><strong>Zero Compute Cost (0.01ms CPU)</strong>: Native Go standard library math execution; runs in nanoseconds with zero GPU/VRAM footprint.</li><li><strong>Holt&#39;s Double Exponential Smoothing</strong>: Measures baseline hourly spend rates ($\\ell_t$) and acceleration trends ($b_t$) to project month-end budgets with $95%$ statistical confidence intervals ($\\pm 8%$).</li><li><strong>Early Budget Overrun Warnings</strong>: Highlights projected budget overruns weeks before they occur so FinOps teams can adjust resource limits proactively.</li></ul><hr><h2 id="enterprise-authentication-access-control" tabindex="-1">Enterprise Authentication &amp; Access Control <a class="header-anchor" href="#enterprise-authentication-access-control" aria-label="Permalink to &quot;Enterprise Authentication &amp; Access Control&quot;">​</a></h2><p>Slicemeter provides enterprise-grade authentication options designed for modern security compliance:</p><ul><li><strong>WebAuthn &amp; Passkeys</strong>: Biometric authentication (Apple TouchID, FaceID, Windows Hello) and hardware security keys (YubiKey) for passwordless access.</li><li><strong>Enterprise SSO &amp; SAML/OIDC</strong>: Seamless integration with Okta, Microsoft Entra ID (Azure AD), Google Workspace, and Keycloak.</li><li><strong>Automated Tenant Onboarding</strong>: Instant cluster API key provisioning upon subscription.</li></ul><hr><h2 id="technical-architecture-stack" tabindex="-1">Technical Architecture Stack <a class="header-anchor" href="#technical-architecture-stack" aria-label="Permalink to &quot;Technical Architecture Stack&quot;">​</a></h2><ul><li><strong>In-Cluster Agent</strong>: Go, Prometheus DCGM Collector, eBPF Uprobes (<code>cilium/ebpf</code>), BadgerDB embedded store.</li><li><strong>Proxy &amp; Webhook</strong>: Token sidecar reverse proxy + Mutating Admission Webhook controller.</li><li><strong>Control Plane API Server</strong>: Go HTTP REST server with dual SQLite / PostgreSQL telemetry persistence.</li><li><strong>Dashboard UI</strong>: Next.js 16, TypeScript, Tailwind CSS, Recharts.</li></ul>',31)])])}const k=i(l,[["render",c]]);export{S as __pageData,k as default};
